package com.resumeanalyzer.service;
import com.resumeanalyzer.dto.*; import com.resumeanalyzer.entity.User; import com.resumeanalyzer.exception.*; import com.resumeanalyzer.repository.UserRepository; import com.resumeanalyzer.security.JwtService; import lombok.RequiredArgsConstructor; import org.springframework.security.authentication.BadCredentialsException; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Instant; import java.time.temporal.ChronoUnit; import java.util.UUID;
@Service @RequiredArgsConstructor public class AuthService { private final UserRepository users; private final PasswordEncoder encoder; private final JwtService jwt; private final EmailVerificationService verification; @Transactional public AuthResponse register(AuthRequest request){String email=request.email().trim().toLowerCase();if(request.fullName()==null||request.fullName().isBlank())throw new BadRequestException("Full name is required for registration");if(users.existsByEmailIgnoreCase(email))throw new BadRequestException("An account already exists for this email");User user=users.save(User.builder().email(email).password(encoder.encode(request.password())).fullName(request.fullName().trim()).role(User.Role.ROLE_USER).emailVerified(false).verificationToken(UUID.randomUUID().toString()).verificationExpiresAt(Instant.now().plus(24,ChronoUnit.HOURS)).build());verification.send(user);return new AuthResponse(null,null,0,user.getFullName(),user.getRole().name(),false,"Please verify your email before signing in.");} @Transactional public void verify(String token){User user=users.findByVerificationToken(token).orElseThrow(()->new BadRequestException("Invalid verification link"));if(user.isEmailVerified())return;if(user.getVerificationExpiresAt()==null||user.getVerificationExpiresAt().isBefore(Instant.now()))throw new BadRequestException("This verification link has expired");user.setEmailVerified(true);user.setVerificationToken(null);user.setVerificationExpiresAt(null);users.save(user);} @Transactional(readOnly=true) public AuthResponse login(AuthRequest request){User user=users.findByEmailIgnoreCase(request.email().trim()).orElseThrow(()->new BadCredentialsException("Invalid email or password"));if(!encoder.matches(request.password(),user.getPassword()))throw new BadCredentialsException("Invalid email or password");if(!user.isEmailVerified())throw new BadCredentialsException("Please verify your email before signing in");return response(user);} private AuthResponse response(User user){return new AuthResponse(jwt.generate(user),"Bearer",jwt.expirationSeconds(),user.getFullName(),user.getRole().name(),user.isEmailVerified(),"Signed in successfully.");} }
